package io.knowledgebrain.notification;
import java.util.*;import java.time.Duration;import java.nio.charset.StandardCharsets;
import org.apache.kafka.clients.consumer.*;import org.apache.kafka.common.*;import org.apache.kafka.common.errors.WakeupException;
import org.springframework.context.SmartLifecycle;import io.micrometer.core.instrument.MeterRegistry;import org.slf4j.LoggerFactory;
 final class NotificationConsumer implements SmartLifecycle {
 private final NotificationStore store;private final DispatchSnapshot snapshot;private final Properties options;private final MeterRegistry metrics;
 private volatile KafkaConsumer<String,byte[]> client;private volatile Thread thread;private volatile boolean running,joined;
 NotificationConsumer(NotificationStore store,DispatchSnapshot snapshot,Properties options,MeterRegistry metrics){this.store=store;this.snapshot=snapshot;this.options=options;this.metrics=metrics;}
 static boolean gap(Long committed,long first,long end){return first<0||end<first||committed==null&&first>0||committed!=null&&(committed<first||committed>end);}
 public void start(){if(running)return;running=true;thread=Thread.ofVirtual().name("notification-in-app-kafka").start(()->{while(running){try(var c=new KafkaConsumer<String,byte[]>(options)){client=c;joined=false;c.subscribe(List.of(DispatchEvent.TOPIC),new ConsumerRebalanceListener(){public void onPartitionsRevoked(Collection<TopicPartition> partitions){joined=false;}public void onPartitionsAssigned(Collection<TopicPartition> partitions){var committed=c.committed(Set.copyOf(partitions));var first=c.beginningOffsets(partitions);var end=c.endOffsets(partitions);boolean recover=!store.seeded();for(var p:partitions){var v=committed.get(p);recover|=gap(v==null?null:v.offset(),first.get(p),end.get(p));}if(recover){snapshot.backfill(store);for(var p:partitions)c.seek(p,end.get(p));metrics.counter("brain.notification.recovery","outcome","canonical").increment();}else for(var p:partitions){var v=committed.get(p);c.seek(p,v==null?first.get(p):v.offset());}joined=true;}});while(running){for(var record:c.poll(Duration.ofSeconds(1))){var headers=new HashMap<String,String>();for(var h:record.headers())if(h.value()==null||headers.putIfAbsent(h.key(),new String(h.value(),StandardCharsets.UTF_8))!=null)throw DispatchEvent.bad();DispatchEvent.transport(record.topic(),record.key(),headers,record.value());boolean delivered=store.accept(record.value());c.commitSync(Map.of(new TopicPartition(record.topic(),record.partition()),new OffsetAndMetadata(record.offset()+1)));metrics.counter("brain.notification.events","outcome",delivered?"delivered":"no-inbox-item").increment();}}}catch(WakeupException e){if(!running)break;}catch(RuntimeException e){metrics.counter("brain.notification.failures","operation","consume").increment();LoggerFactory.getLogger(getClass()).warn("in_app_delivery retry failure={}; failed event remains unacknowledged",e.getClass().getSimpleName());}finally{client=null;joined=false;}if(running)try{Thread.sleep(500);}catch(InterruptedException e){Thread.currentThread().interrupt();break;}}});}
 boolean ready(){return running&&joined&&store.seeded();}public boolean isRunning(){return running;}
 public void stop(){running=false;var c=client;if(c!=null)c.wakeup();if(thread!=null)try{thread.join(15000);}catch(InterruptedException e){Thread.currentThread().interrupt();}}
}
